# API key generator + validator with scoping, hashing, revocation.
# Illustrative mock — not for production.
import secrets, hashlib, time
from typing import Optional

# Server-side registry: key_id -> {hash, owner, scopes, exp, revoked}
KEYS = {}

def generate_key(owner: str, scopes: list[str], ttl_days: int = 90,
                 prefix: str = "sk_live_") -> tuple[str, str]:
    """Create a new API key. Returns (key_id, plaintext_key)."""
    raw = secrets.token_bytes(32)                      # 256 bits of entropy
    secret = prefix + raw.hex()                        # sk_live_<hex>
    key_id = "kid_" + secrets.token_urlsafe(8)         # public identifier
    key_hash = hashlib.sha256(secret.encode()).hexdigest()
    KEYS[key_id] = {
        "hash": key_hash, "owner": owner, "scopes": set(scopes),
        "exp": int(time.time()) + ttl_days * 86400,
        "revoked": False, "created": int(time.time()),
    }
    return key_id, secret                              # secret shown ONCE

def validate_key(secret: str, required_scope: str) -> Optional[dict]:
    """Validate an incoming API key against the registry."""
    if not secret or len(secret) < 16:
        return None
    h = hashlib.sha256(secret.encode()).hexdigest()
    for kid, meta in KEYS.items():
        if not _consttime_eq(meta["hash"], h):
            continue
        if meta["revoked"]:
            return {"valid": False, "reason": "revoked", "key_id": kid}
        if time.time() > meta["exp"]:
            return {"valid": False, "reason": "expired", "key_id": kid}
        if required_scope and required_scope not in meta["scopes"]:
            return {"valid": False, "reason": "forbidden",
                    "key_id": kid, "scopes": list(meta["scopes"])}
        return {"valid": True, "key_id": kid, "owner": meta["owner"],
                "scopes": list(meta["scopes"])}
    return None  # no match -> treat as 401

def revoke_key(key_id: str) -> bool:
    if key_id in KEYS:
        KEYS[key_id]["revoked"] = True
        return True
    return False

def _consttime_eq(a: str, b: str) -> bool:
    return len(a) == len(b) and secrets.compare_digest(a, b)

if __name__ == "__main__":
    kid, sk = generate_key("billing-svc", ["charges:write", "customers:read"])
    print("issued:", sk[:14], "...", sk[-4:])
    print("validate ok:", validate_key(sk, "charges:write"))
    print("wrong scope:", validate_key(sk, "payouts:write"))
    print("after revoke:", (revoke_key(kid), validate_key(sk, "charges:write")))
